package com.kancrutt.gigginggear;

import android.content.Context;
import android.util.Log;

import org.json.JSONArray;
import org.json.JSONObject;

import java.io.InputStream;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;

/** Curated catalog policy for the guitar signal chain.
 *
 *  Since Phase 2 the curation is data-driven: assets/curated_plugins.json
 *  lists every bundled plugin (lowercased name) that is exposed in the
 *  browse list. The list is generated by tools/metadata_audit/build_catalog.py
 *  from all_plugins.json + lv2_plugins.json minus the reviewed blacklist
 *  (lab DSP, MIDI-only synths, mastering tools, policy items).
 *
 *  Policy rules below still apply on top of the list:
 *    - exactly one NAM loader (NG), legacy NAM and AIDA-X stay out
 *    - exactly two IR loaders: Simple IR Loader and x42 IR convolver
 *
 *  assets/blacklist.json is loaded first and its entries are always
 *  rejected, in the browse list, in the add dialog and in preset load alike,
 *  so a single guard file decides visibility everywhere (the browse list
 *  used to ignore it, which re-exposed a crashy plugin that the dialog
 *  still hid).
 *
 *  If the asset is missing/corrupt the legacy name-token heuristics are
 *  used so the catalog is never empty. */
final class GuitarPluginCatalog {
    private static final String TAG = "GuitarPluginCatalog";
    private static final String ASSET = "curated_plugins.json";
    private static final String BLACKLIST_ASSET = "blacklist.json";

    /** Lowercased curated names; null until init()/loadFromJson(). */
    private static Set<String> sCuratedNames;
    /** Lowercased blacklisted names; null until init()/loadBlacklistFromJson(). */
    private static Set<String> sBlacklistNames;

    private GuitarPluginCatalog() {}

    /** Load the curated catalog asset. Safe to call more than once. */
    static void init(Context context) {
        if (sCuratedNames != null || context == null) return;
        // Blacklist first: loadFromJson()/isCurated() consult it.
        loadBlacklistAsset(context);
        try {
            InputStream is = context.getAssets().open(ASSET);
            StringBuilder sb = new StringBuilder();
            byte[] buf = new byte[8192];
            int r;
            while ((r = is.read(buf)) > 0) {
                sb.append(new String(buf, 0, r, "UTF-8"));
            }
            is.close();
            loadFromJson(sb.toString());
        } catch (Throwable t) {
            try { Log.w(TAG, "curated catalog asset unavailable, using legacy rules", t); } catch (Throwable ignored) { }
            sCuratedNames = null;
        }
    }

    /** Read assets/blacklist.json ({"name": 1} map). Missing asset = no blacklist. */
    private static void loadBlacklistAsset(Context context) {
        try {
            InputStream is = context.getAssets().open(BLACKLIST_ASSET);
            StringBuilder sb = new StringBuilder();
            byte[] buf = new byte[8192];
            int r;
            while ((r = is.read(buf)) > 0) {
                sb.append(new String(buf, 0, r, "UTF-8"));
            }
            is.close();
            loadBlacklistFromJson(sb.toString());
        } catch (Throwable t) {
            try { Log.w(TAG, "blacklist asset unavailable, no names blocked", t); } catch (Throwable ignored) { }
            sBlacklistNames = null;
        }
    }

    /** Parse blacklist JSON; package-private for unit tests. */
    static void loadBlacklistFromJson(String json) {
        try {
            JSONObject root = new JSONObject(json);
            Set<String> set = new HashSet<>();
            java.util.Iterator<String> it = root.keys();
            while (it.hasNext()) {
                String k = it.next();
                if (k == null || k.trim().isEmpty()) continue;
                if (root.optInt(k, 0) == 0) continue;
                set.add(k.toLowerCase(Locale.US).trim());
            }
            sBlacklistNames = set;
            try { Log.i(TAG, "blacklist loaded: " + set.size() + " names"); } catch (Throwable ignored) { }
        } catch (Throwable t) {
            try { Log.e(TAG, "failed to parse blacklist asset", t); } catch (Throwable ignored) { }
            sBlacklistNames = null;
        }
    }

    /** Parse the asset JSON; package-private for unit tests. */
    static void loadFromJson(String json) {
        try {
            JSONObject root = new JSONObject(json);
            JSONArray arr = root.getJSONArray("names");
            Set<String> set = new HashSet<>();
            for (int i = 0; i < arr.length(); i++) {
                String n = arr.optString(i, "");
                if (!n.isEmpty()) set.add(n.toLowerCase(Locale.US).trim());
            }
            if (set.isEmpty()) throw new IllegalStateException("empty name list");
            sCuratedNames = set;
            try { Log.i(TAG, "curated catalog loaded: " + set.size() + " plugins"); } catch (Throwable ignored) { }
        } catch (Throwable t) {
            try { Log.e(TAG, "failed to parse curated catalog asset", t); } catch (Throwable ignored) { }
            sCuratedNames = null;
        }
    }

    /** Test helper: drop the in-memory list (back to legacy fallback). */
    static void clearForTesting() {
        sCuratedNames = null;
        sBlacklistNames = null;
    }

    static boolean isCurated(String pluginName) {
        if (pluginName == null || pluginName.trim().isEmpty()) return false;
        String n = pluginName.toLowerCase(Locale.US).trim();

        // Policy rules, always applied independent of the asset:
        // Keep exactly one NAM loader. NG is the selected A2-capable loader
        // (mikeoliphant/neural-amp-modeler-lv2, NeuralAudio engine); legacy
        // NAM and AIDA-X must not create duplicate choices.
        if (n.contains("neural amp modeler") && !n.contains("ng")) return false;
        if (n.equals("aida-x")) return false;
        // Deep-research curation (Hery): exactly ONE IR-cab loader and ONE
        // convolution reverb, the best-feature / most-updated of each.
        //   cab IR loader  -> "x42 - IR Convolver Mono => Stereo" (zconvo.lv2,
        //       Robin Gareus' current convolver; supersedes the deprecated
        //       convoLV2 & zeroconvo). All other IR/impulse loaders are out:
        //       Simple IR Loader (crashy brnv bundle), brummer10 Impulse
        //       Loader, Reverbtron, swh impulse, irdsp (unverifiable origin).
        //   conv reverb    -> "convolv2" (convoLV2, the shipped+working
        //       convolution reverb; recategorized CABINET -> REVERB).
        // Note: "convolution" is deliberately NOT a reject token - ConvoLV2
        // "Convolution Reverb" is the kept guitar reverb.
        if (n.contains("ir loader") || n.contains("impulse loader")
                || n.contains("ir convolver")
                || n.contains("reverbtron") || n.contains("swh impulse")
                || n.equals("irdsp")) {
            if (!n.equals("x42 - ir convolver mono => stereo")) {
                return false;
            }
        }

        // Blacklist is enforced centrally now (Blacklist.java, keyed by
        // stable key); nothing to do here.

        if (sCuratedNames != null) return sCuratedNames.contains(n);

        // Legacy fallback when the asset is missing: name-token heuristics.
        for (String reject : LEGACY_REJECT) {
            if (n.contains(reject)) return false;
        }
        for (String family : LEGACY_FAMILIES) {
            if (n.contains(family)) return true;
        }
        return false;
    }

    private static final String[] LEGACY_REJECT = {
            "testtone", "test tone", "signal generator", "sinus wave", "constant signal",
            "vocoder", "beatbox", "epiano", "piano", "dx10", "jx10", "shepard",
            "cellular automaton", "tracker", "sequence", "matrix", "spatialiser",
            "surround", "splitter", "demuxer", "sifter", "hilbert", "allpass",
            "comb filter", "comb delay", "allpass delay", "frequency shifter",
            "bode frequency", "artificial latency", "declipper", "inverter",
            "dc offset", "decimator", "deesser", "dither", "darc", "ringmod",
            "ring mod", "talkbox", "gong", "transient mangler", "crossfade",
            "delay line", "delayorama", "fractionally addressed", "modulatable delay",
            "l/c/r delay", "state variable filter", "ls filter", "frequency tracker",
            "autotalent", "bode", "pointer cast", "wave shaper", "sinus",
            "smooth decimator"
    };

    private static final String[] LEGACY_FAMILIES = {
            "gx", "rkr ", "c* ", "tap ", "gnuitar", "neural amp", "aida-x",
            "fonin", "poweramp", "preamp", "cab", "impulse", "convo", "ir loader",
            "ir convolver", "convolution", "reverbtron", "swh impulse",
            "mda combo", "mda overdrive", "mda delay", "mda dubdelay", "mda dynamics",
            "mda limiter", "mda rezfilter", "mda leslie", "mda detune",
            "invada", "fast overdrive", "valve preamplifier", "valve saturation",
            "tape delay", "plate reverb", "simple amplifier", "tone stack",
            "compressor", "noisegate", "noise gate", "eq", "equalizer", "phaser",
            "flanger", "chorus", "vibrato", "tremolo", "wah", "reverb", "delay",
            "pitch shifter", "octave", "limiter", "gate", "fuzz", "distortion",
            "overdrive", "booster", "boost", "cabinet", "room simulator"
    };
}
